import '../../../globals.js';
export const isWindingIncluded = (windingNumber, fillRule) => {
    switch (fillRule) {
        case 'nonzero':
            return windingNumber !== 0;
        case 'evenodd':
            return windingNumber % 2 !== 0;
        case 'positive':
            return windingNumber > 0;
        case 'negative':
            return windingNumber < 0;
        default:
            throw new Error('unknown fill rule');
    }
};
